# global.gd - manages global game state and emits signals for UI updates
extends Node

# Signals
signal villagers_updated(saved: int, lost: int, total: int)
signal score_updated(score: int)
signal coins_updated(coins: int)
signal wave_updated(wave: int)
signal time_updated(time: String)

var high_scores: Array[Dictionary] = []
var current_score: int = 0
var current_wave: int = 1
var coins_collected: int = 0
var current_time_survived: float = 0.0
var saved_villagers: int = 0
var lost_villagers: int = 0
var total_villagers: int = 50
var game_active: bool = true
var boss_fight_active: bool = false
var _boss_triggered: bool = false
var godmode: bool = false
var guard_spawn_index: int = 0
var magi_spawn_index: int = 0

# Shop / scene-transition state preservation
var shop_purchase_counts: Dictionary = {"health": 0, "damage": 0, "speed": 0, "guard": 0, "magi": 0}

func _ready() -> void:
	var window := get_window()
	window.content_scale_mode = Window.CONTENT_SCALE_MODE_VIEWPORT
	window.content_scale_aspect = Window.CONTENT_SCALE_ASPECT_IGNORE
	window.content_scale_size = Vector2i(1152, 648)
	DisplayServer.window_set_mode(DisplayServer.WINDOW_MODE_MAXIMIZED)
	DirAccess.make_dir_absolute("user://saves/")
	load_high_scores()

func _process(delta: float) -> void:
	if game_active:
		current_time_survived += delta
		emit_signal("time_updated", format_time(current_time_survived))

func load_high_scores() -> void:
	var file: FileAccess = FileAccess.open("user://saves/high_scores.json", FileAccess.READ)
	if file:
		var json_data = JSON.parse_string(file.get_as_text())
		if json_data is Array:
			high_scores = []
			for item in json_data:
				if item is Dictionary:
					var entry: Dictionary = {
						"score": int(round(item.get("score", 0.0))),
						"initials": item.get("initials", "AAA").to_upper(),
						"wave": int(round(item.get("wave", 0.0))),
						"coins": int(round(item.get("coins", 0.0))),
						"time_survived": float(item.get("time_survived", 0.0)),
						"saved_villagers": int(round(item.get("saved_villagers", 0.0))),
						"lost_villagers": int(round(item.get("lost_villagers", 0.0)))
					}
					high_scores.append(entry)
		file.close()
	else:
		# File doesn't exist yet - create default empty scores (first run)
		high_scores = []
		save_high_scores()  # Create the file with empty array

func save_high_scores() -> void:
	var dir: DirAccess = DirAccess.open("user://")
	if not dir.dir_exists("saves"):
		dir.make_dir("saves")
	var file: FileAccess = FileAccess.open("user://saves/high_scores.json", FileAccess.WRITE)
	if file:
		file.store_string(JSON.stringify(high_scores, "\t"))
		file.close()
	else:
		push_error("Global: Failed to save high_scores.json")

func add_high_score(score: int, initials: String, wave: int, coins: int, time_survived: float, saved_villagers: int, lost_villagers: int) -> void:
	if initials.length() > 3:
		initials = initials.substr(0, 3)
	if initials.length() == 0:
		initials = "AAA"
	var entry: Dictionary = {
		"score": score,
		"initials": initials.to_upper(),
		"wave": wave,
		"coins": coins,
		"time_survived": time_survived,
		"saved_villagers": saved_villagers,
		"lost_villagers": lost_villagers
	}
	high_scores.append(entry)
	high_scores.sort_custom(func(a, b): return a.score > b.score)
	if high_scores.size() > 10:
		high_scores.resize(10)
	save_high_scores()

func is_high_score(score: int) -> bool:
	if high_scores.size() < 10:
		return true
	return score > high_scores[-1].score

func format_time(seconds: float) -> String:
	var minutes: int = int(seconds / 60)
	var secs: int = int(seconds) % 60
	return "%02d:%02d" % [minutes, secs]

func reset() -> void:
	current_score = 0
	current_wave = 1
	coins_collected = 0
	current_time_survived = 0.0
	saved_villagers = 0
	lost_villagers = 0
	total_villagers = 50
	game_active = true
	boss_fight_active = false
	_boss_triggered = false
	godmode = false
	guard_spawn_index = 0
	magi_spawn_index = 0
	shop_purchase_counts = {"health": 0, "damage": 0, "speed": 0, "guard": 0, "magi": 0}
	emit_signal("score_updated", current_score)
	emit_signal("coins_updated", coins_collected)
	emit_signal("wave_updated", current_wave)
	emit_signal("time_updated", format_time(current_time_survived))
	emit_signal("villagers_updated", saved_villagers, lost_villagers, total_villagers)

func increment_wave() -> void:
	current_wave += 1
	emit_signal("wave_updated", current_wave)

func increment_saved_villagers() -> void:
	saved_villagers += 1
	emit_signal("villagers_updated", saved_villagers, lost_villagers, total_villagers)
	if saved_villagers >= total_villagers and not _boss_triggered and not boss_fight_active:
		_boss_triggered = true
		_start_boss_sequence()

func increment_lost_villagers() -> void:
	lost_villagers += 1
	emit_signal("villagers_updated", saved_villagers, lost_villagers, total_villagers)

func _start_boss_sequence() -> void:
	boss_fight_active = true
	for spawner in get_tree().get_nodes_in_group("villager_spawner"):
		if spawner.has_method("stop_spawning"):
			spawner.stop_spawning()
	for mob in get_tree().get_nodes_in_group("monsters"):
		if is_instance_valid(mob):
			mob.queue_free()
	var ui := get_node_or_null("/root/UI")
	if ui and ui.has_method("show_announcement"):
		ui.show_announcement("50 Villagers Saved!\nMh'orzath awakens...", 4.0)
	if ui and ui.has_method("chat_add"):
		ui.chat_add("The darkness recoils... something far worse stirs.", "System")
	await get_tree().create_timer(3.5).timeout
	if not game_active:
		return
	_spawn_boss()

func _spawn_boss() -> void:
	var boss_scene: PackedScene = load("res://Scenes/mh_orzath.tscn")
	if not boss_scene:
		push_error("Global: Could not load mh_orzath.tscn!")
		return
	var boss: Node2D = boss_scene.instantiate() as Node2D
	boss.global_position = _get_boss_spawn_position()
	get_tree().current_scene.add_child(boss)
	if boss.has_signal("mob_died"):
		boss.mob_died.connect(_on_boss_died)

func _get_boss_spawn_position() -> Vector2:
	var player := get_tree().get_first_node_in_group("player")
	var base: Vector2 = player.global_position if player and is_instance_valid(player) else Vector2(600.0, 400.0)
	var viewport_rect := get_viewport().get_visible_rect()
	return base + Vector2(0.0, -(viewport_rect.size.y * 0.5 + 200.0))

func _on_boss_died() -> void:
	game_active = false
	var ui := get_node_or_null("/root/UI")
	if ui:
		ui.visible = false
	get_tree().call_deferred("change_scene_to_file", "res://Scenes/victory_scene.tscn")

		if is_instance_valid(healer) and healer is CharacterBody2D:
			var dist := global_position.distance_to(healer.global_position)
			if dist < min_dist:
				min_dist = dist
				nearest = healer as CharacterBody2D
	return nearest

func take_damage(damage: int, _projectile_instance) -> void:
	current_health -= damage

	if health_bar and is_instance_valid(health_bar):
		health_bar.value = current_health

	if current_health <= 0:
		_die()
	else:
		_damage_flash()

func _damage_flash() -> void:
	if sprite and is_instance_valid(sprite):
		sprite.modulate = Color.RED
		await get_tree().create_timer(0.05).timeout
		sprite.modulate = Color.WHITE

func _die() -> void:

	if get_parent() is NodePool:
		get_parent().despawn(self)
	else:
		visible = false
		set_process(false)
		set_physics_process(false)

		if $CollisionShape2D:
			$CollisionShape2D.set_deferred("disabled", true)

func _on_detection_area_body_entered(body: Node2D) -> void:
	if body.is_in_group("monsters") and body.visible and body is CharacterBody2D and not detected_monsters.has(body):
		detected_monsters.append(body)

func _on_detection_area_body_exited(body: Node2D) -> void:
	if detected_monsters.has(body):
		detected_monsters.erase(body)

func get_health() -> int:
	return current_health

func get_max_health() -> int:
	return max_health

func heal(amount: int) -> void:
	current_health = clamp(current_health + amount, 0, max_health)

	if health_bar and is_instance_valid(health_bar):
		health_bar.value = current_health


func set_damage_modifier(modifier: float) -> void:
	damage_modifier = modifier

func apply_speed_buff(bonus_percent: float, duration: float) -> void:
	var saved_speed := max_speed
	max_speed *= (1.0 + bonus_percent)
	var timer := Timer.new()
	timer.wait_time = duration
	timer.one_shot = true
	timer.timeout.connect(func():
		max_speed = saved_speed
		timer.queue_free()
	)
	add_child(timer)
	timer.start()

func _damage_flash() -> void:
	if sprite and is_instance_valid(sprite):
		sprite.modulate = Color.CYAN
		await get_tree().create_timer(0.05).timeout
		sprite.modulate = Color.WHITE

func _die() -> void:
	died.emit()
	visible = false
	set_process(false)
	set_physics_process(false)
	if $CollisionShape2D and is_instance_valid($CollisionShape2D):
		$CollisionShape2D.set_deferred("disabled", true)

# projectile.gd - base projectile template script
extends Area2D


@export var speed : float = 200.0
@export var owner_group: String
@export var damage : int = 4
@export var sound_stream : AudioStream
@onready var destroy_timer : Timer = $destroy_timer
@onready var projectile_sound : AudioStreamPlayer2D = $projectile_sound
@onready var collision_shape : CollisionShape2D = $CollisionShape2D

var move_direction : Vector2 = Vector2.ZERO
var home_target: Node = null
@export var home_strength: float = 0.0  # turn rate radians/sec; 0 = straight flight
var slow_percent: float = 0.0
var slow_duration: float = 0.0

func _ready() -> void:
	if not is_connected("body_entered", Callable(self, "_on_body_entered")):
		connect("body_entered", Callable(self, "_on_body_entered"))

	visible = true
	if collision_shape:
		collision_shape.disabled = false
	if projectile_sound:
		if sound_stream:
			projectile_sound.stream = sound_stream
		if not projectile_sound.playing:
			projectile_sound.play()
	else:
		push_warning("Projectile %s: projectile_sound or sound_stream is null in _ready—check scene node!" % name)



func reset() -> void:
	visible = true
	if collision_shape:
		collision_shape.set_deferred("disabled", false)
	if destroy_timer:
		destroy_timer.start()
	if projectile_sound:
		if sound_stream:
			projectile_sound.stream = sound_stream
		if not projectile_sound.playing:
			projectile_sound.play()
	home_target = null
	move_direction = Vector2.ZERO
	rotation = 0.0
	position = Vector2.ZERO
	slow_percent = 0.0
	slow_duration = 0.0
	modulate = Color.WHITE


func _process(delta: float) -> void:
	if home_target != null and is_instance_valid(home_target) and home_strength > 0.0:
		var to_target: Vector2 = global_position.direction_to(home_target.global_position)
		var turn: float = clamp(move_direction.angle_to(to_target), -home_strength * delta, home_strength * delta)
		move_direction = move_direction.rotated(turn).normalized()
	if move_direction != Vector2.ZERO:
		translate(move_direction * speed * delta)
		rotation = move_direction.angle()


func _on_destroy_timer_timeout() -> void:
	despawn()


func _on_visibility_changed() -> void:
	if visible and destroy_timer:
		destroy_timer.start()


func _on_body_entered(body: Node) -> void:

	if body.is_in_group(owner_group):
		return

	if owner_group == "friendly":
		if body.has_method("heal") and (body.is_in_group("player") or body.is_in_group("friendly")):
			push_warning("Friendly projectile tried to heal in projectile.gd; should be in healing_projectile.gd")
			despawn()
			return

	if body.has_method("take_damage") and body.is_in_group("monsters"):
		body.take_damage(damage, self)
		if slow_percent > 0.0 and body.has_method("apply_slow"):
			body.apply_slow(slow_percent, slow_duration)
		despawn()
		return

	if owner_group == "monsters":
		if body.has_method("take_damage") and (body.is_in_group("player") or body.is_in_group("friendly") or body.is_in_group("healer")):
			body.take_damage(damage, self)
			despawn()
			return

	if owner_group == "player" and body.has_method("take_damage") and body.is_in_group("monsters"):
		body.take_damage(damage, self)
		despawn()
		return

	despawn()


func despawn() -> void:
	visible = false
	if collision_shape:
		collision_shape.set_deferred("disabled", true)
	if destroy_timer:
		destroy_timer.stop()
	if projectile_sound and projectile_sound.playing:
		projectile_sound.stop()
	if get_parent() is NodePool:
		get_parent().despawn(self)


func set_damage(new_damage: int) -> void:
	damage = new_damage


func launch(start_pos: Vector2, direction: Vector2) -> void:
	global_position = start_pos
	move_direction = direction.normalized()
	rotation = move_direction.angle()

	visible = true
	if $CollisionShape2D:
		$CollisionShape2D.disabled = false

	if projectile_sound and projectile_sound.stream == null:
		projectile_sound.stream = load("res://Assets/sounds/bone_whistle.ogg")
	if projectile_sound:
		projectile_sound.play()

	if destroy_timer:
		destroy_timer.start()

		if Global.is_high_score(Global.current_score):
			get_tree().call_deferred("change_scene_to_file", "res://Scenes/game_over.tscn")
		else:
			get_tree().call_deferred("change_scene_to_file", "res://Scenes/game_over2.tscn")
	else:
		push_error("SceneTree is null—cannot change to game over scene!")

func take_damage(damage: int, _projectile_instance) -> void:
	if Global.godmode:
		return
	current_health -= damage
	if health_bar and is_instance_valid(health_bar):
		health_bar.value = current_health
	emit_signal("health_updated", current_health, max_health)
	var camera := get_viewport().get_camera_2d()
	if camera and camera.has_method("shake"):
		camera.shake(5.0, 0.2)
	if current_health <= 0:
		_handle_game_over()
	else:
		if player_damage_sound:
			player_damage_sound.play()

func open_fire() -> void:
	# Fire an arrow projectile
	last_shoot_time = Time.get_unix_time_from_system()
	var arrow = arrow_pool.spawn()
	arrow.global_position = muzzle.global_position
	arrow.owner_group = "player"

	# FIXED: Use cached aim_vector instead of recalculating
	var aim_vector: Vector2 = cached_aim_vector
	if aim_vector.is_zero_approx():
		# Fallback if no aim input
		aim_vector = muzzle.global_position.direction_to(get_global_mouse_position())

	arrow.move_direction = aim_vector
	if arrow.has_method("set_damage"):
		arrow.set_damage(base_damage * damage_modifier)


func _move_wobble() -> void:
	# Handle sprite wobble animation
	var rot: float = sin(Time.get_ticks_msec() / 100.0) * 2
	sprite.rotation_degrees = rot

func _on_regeneration_timer_timeout() -> void:
	# Regenerate health periodically
	if is_queued_for_deletion():
		return
	var health_to_add: int = int(regeneration_per_second)
	current_health += health_to_add
	current_health = clamp(current_health, 0, max_health)
	if health_bar and is_instance_valid(health_bar):
		health_bar.value = current_health
	emit_signal("health_updated", current_health, max_health)

func _on_pickup_area_entered(area: Area2D) -> void:
	# Handle loot pickup when entering pickup area
	if area.is_in_group("loot"):

	sprite.rotation_degrees = rot

func _cast() -> void:
	# Fire projectile at the current attack target
	last_shoot_time = Time.get_unix_time_from_system()
	if not bullet_pool or not muzzle or not target:
		push_warning("Monster %s: Cannot cast!" % name)
		return

	if not is_instance_valid(target):
		target = null
		push_warning("Monster %s: Target instance invalid during cast!" % name)
		return

