# mh_orzath.gd - Final Boss: Mh'orzath, the Eclipsed One
extends "res://Scripts/monsters.gd"

const BOSS_MUSIC: AudioStreamMP3 = preload("res://Assets/Audio/audiodollar-adventure-game-334657.mp3")

const ARRIVAL_MESSAGE: String = "Your meddling has drawn the ire of Mh'orzath, the Eclipsed One! Tremble in fear!"

@export var event_horizon_range: float = 300.0
@export var event_horizon_damage: int = 160
@export var event_horizon_pull_strength: float = 600.0
@export var event_horizon_cooldown: float = 15.0

@export var nihil_storm_range: float = 400.0
@export var nihil_storm_damage: int = 200
@export var nihil_storm_cooldown: float = 20.0

# Stagger the first uses so player has a moment to react
var _event_horizon_timer: float = 8.0
var _nihil_storm_timer: float = 14.0

func _ready() -> void:
	score_value = 10000
	# Override inherited monster defaults to boss-level values
	shoot_rate = 0.8       # monsters.gd default is 1.5 — boss fires nearly 2x faster
	shoot_range = 350.0    # longer reach so he doesn't have to chase
	max_speed = 65.0       # was 45 — more mobile and harder to kite
	super._ready()
	add_to_group("final_boss")
	call_deferred("_on_boss_spawned")

func _on_boss_spawned() -> void:
	Global.boss_fight_active = true
	_clear_regular_monsters()
	_respawn_allies()
	_enable_magi_vulnerability()
	_start_boss_music()
	var ui = get_node_or_null("/root/UI")
	if ui and ui.has_method("show_announcement"):
		ui.show_announcement(ARRIVAL_MESSAGE)

func _start_boss_music() -> void:
	var existing := get_tree().current_scene.get_node_or_null("AudioStreamPlayer")
	if existing is AudioStreamPlayer:
		existing.stop()
	var stream := BOSS_MUSIC.duplicate() as AudioStreamMP3
	stream.loop = true
	var player := AudioStreamPlayer.new()
	player.stream = stream
	player.volume_db = -2.0
	get_tree().current_scene.add_child(player)
	player.play()

func _process(delta: float) -> void:
	super._process(delta)
	if not visible:
		return
	_event_horizon_timer -= delta
	_nihil_storm_timer -= delta
	if _event_horizon_timer <= 0.0:
		_cast_event_horizon()

extends Camera2D

@onready var target = $"../player"
@export var follow_rate: float = 2.0

# The vertical world-units the game was designed to show at 1x zoom.
# Matches the Godot 4 default viewport height so existing scenes look unchanged.
@export var base_height: float = 648.0

# Screen shake
var _shake_intensity: float = 0.0
var _shake_timer: float = 0.0

# Zoom — user_zoom is applied on top of the auto-fit base zoom
var _base_zoom: float = 1.0
var _user_zoom: float = 1.0
var _pinch_start_user_zoom: float = 1.0
var _pinch_start_distance: float = 0.0
var _touch_positions: Dictionary = {}

func _ready() -> void:
	get_viewport().size_changed.connect(_recalc_zoom)
	_recalc_zoom()

func shake(intensity: float, duration: float) -> void:
	_shake_intensity = intensity
	_shake_timer = duration

func _process(delta: float) -> void:
	global_position = global_position.lerp(target.global_position, follow_rate * delta)
	if _shake_timer > 0.0:
		_shake_timer -= delta
		offset = Vector2(
			randf_range(-_shake_intensity, _shake_intensity),
			randf_range(-_shake_intensity, _shake_intensity)
		)
	else:
		offset = Vector2.ZERO

func _recalc_zoom() -> void:
	# Scale so base_height world-units always fill the viewport vertically.
	var vp_h := get_viewport().get_visible_rect().size.y
	if vp_h > 0.0:
		_base_zoom = vp_h / base_height
	zoom = Vector2.ONE * (_base_zoom * _user_zoom)

func _unhandled_input(event: InputEvent) -> void:
	# Mouse-wheel zoom
	if event is InputEventMouseButton and event.is_pressed():
		if event.button_index == MOUSE_BUTTON_WHEEL_UP:
			_user_zoom *= 1.1
			_recalc_zoom()
		elif event.button_index == MOUSE_BUTTON_WHEEL_DOWN:
			_user_zoom /= 1.1
			_recalc_zoom()

	# Touch: track finger positions
	if event is InputEventScreenTouch:
		if event.pressed:
			_touch_positions[event.index] = event.position
		else:
			_touch_positions.erase(event.index)
			if _touch_positions.size() < 2:
				_pinch_start_distance = 0.0

	# Pinch-to-zoom
	if _touch_positions.size() == 2:
		var pts := _touch_positions.values()
		var dist: float = pts[0].distance_to(pts[1])
		if _pinch_start_distance == 0.0:
			_pinch_start_distance = dist
			_pinch_start_user_zoom = _user_zoom
			return
		_user_zoom = _pinch_start_user_zoom * (dist / _pinch_start_distance)
		_recalc_zoom()

