		return

	var left   := used.position.x * TILE_SIZE
	var top    := used.position.y * TILE_SIZE
	var right  := (used.position.x + used.size.x) * TILE_SIZE
	var bottom := (used.position.y + used.size.y) * TILE_SIZE

